package nova;

import com.fasterxml.jackson.databind.*;
import java.net.*;
import java.net.http.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public final class CoreTest {
  private static final ObjectMapper JSON = new ObjectMapper();

  private CoreTest() {}

  public static void main(String[] args) throws Exception {
    String hash = Passwords.hash("MigrationPassword123");
    assert Passwords.verify("MigrationPassword123", hash);
    // Generated by argon2::Argon2::default() in the existing Rust server.
    assert Passwords.verify(
        "MigrationPassword123",
        "$argon2id$v=19$m=19456,t=2,p=1$Tm92YU1pZ3JhdGlvbjEyMw$wIu2gcAu4eOwNHEeXDhcUUD3xakVg6o9jDeC+ipLZdc");
    assert !Passwords.verify("wrong", hash);
    assert !Passwords.verify("test", "$argon2id$v=19$m=999999999,t=2,p=1$YWJjZA$YWJjZA");
    assert EpisodeLocale.key(" Plan B ").equals(EpisodeLocale.key("Plan B"));
    var rooms = new Rooms();
    String id = rooms.create(1, 2, 3, null, 12, "Хост");
    var room = rooms.get(id);
    var subscriptions = new ArrayList<Rooms.Subscription>();
    for (long i = 1; i <= 50; i++)
      subscriptions.add(room.join(Map.of("id", i, "name", "Зритель " + i)));
    assert ((List<?>) room.snapshot().get("members")).size() == 50;
    for (var subscription : subscriptions) subscription.events.clear();
    try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
      var tasks = new ArrayList<Callable<Map<String, Object>>>();
      for (int i = 0; i < 50; i++) {
        int n = i;
        tasks.add(() -> room.command(3, false, 30 + n, "Зритель " + n));
      }
      for (var result : executor.invokeAll(tasks)) assert result.get().get("revision") != null;
    }
    for (var subscription : subscriptions)
      for (long revision = 1; revision <= 50; revision++)
        assert ((Number) ((Map<?, ?>) subscription.next(1000).get("state")).get("revision"))
                .longValue()
            == revision;
    room.command(3, true, 50, "Хост");
    for (var subscription : subscriptions) subscription.close();
    assert ((Map<?, ?>) room.snapshot().get("state")).get("playing").equals(true);
    try (var rejoined = room.join(Map.of("id", 1L, "name", "Хост"))) {
      assert ((Map<?, ?>) rejoined.next(1000).get("state")).get("playing").equals(true);
    }
    Path temp = Files.createTempDirectory("nova-java-test-");
    try (var db = new Database(temp.resolve("nova.db"))) {
      assert ((Number) db.query("PRAGMA user_version").getFirst().values().iterator().next())
              .intValue()
          == 18;
      long now = System.currentTimeMillis();
      db.execute(
          "INSERT INTO users(id,login,name,pass,role,created_at)"
              + " VALUES(1,'viewer','Зритель',?,'viewer',?)",
          hash,
          now);
      db.execute("INSERT INTO profiles(id,user_id,name,created_at) VALUES(1,1,'Зритель',?)", now);
      Path video = temp.resolve("video.mp4");
      byte[] videoBytes = new byte[1024];
      for (int i = 0; i < videoBytes.length; i++) videoBytes[i] = (byte) i;
      Files.write(video, videoBytes);
      db.execute(
          "INSERT INTO titles(id,kind,key,title,added_at,updated_at)"
              + " VALUES(1,'movie','media','Фильм',?,?)",
          now,
          now);
      db.execute(
          "INSERT INTO files(id,title_id,path,size,mtime,added_at) VALUES(1,1,?,1024,0,?)",
          video.toString(),
          now);
      db.execute(
          "INSERT INTO links(kind,url,label,added_at)"
              + " VALUES('direct','https://example.com/test.webm','Фильм',?)",
          now);
      db.setSetting(EpisodeLocale.key("Stick or Twist"), "Пан или пропал");
      try (var locale = new EpisodeLocale(db)) {
        assert locale.localized("Stick or Twist").equals("Пан или пропал");
        assert locale.localized("Untranslated title") == null;
      }
      try (var app = new Main(db, 0, Path.of("web/build"))) {
        app.start();
        String base = "http://127.0.0.1:" + app.port();
        try (var client =
            HttpClient.newBuilder()
                .cookieHandler(new CookieManager(null, CookiePolicy.ACCEPT_ALL))
                .build()) {
          var unauthenticated =
              client.send(
                  HttpRequest.newBuilder(URI.create(base + "/api/me")).GET().build(),
                  HttpResponse.BodyHandlers.ofString());
          assert unauthenticated.statusCode() == 401;
          var csrf =
              client.send(
                  HttpRequest.newBuilder(URI.create(base + "/api/auth/login"))
                      .POST(HttpRequest.BodyPublishers.ofString("{}"))
                      .build(),
                  HttpResponse.BodyHandlers.ofString());
          assert csrf.statusCode() == 403;
          var login =
              post(
                  client,
                  base + "/api/auth/login",
                  Map.of("login", "viewer", "password", "MigrationPassword123"));
          assert login.statusCode() == 200 : login.body();
          var me =
              client.send(
                  HttpRequest.newBuilder(URI.create(base + "/api/me")).GET().build(),
                  HttpResponse.BodyHandlers.ofString());
          assert me.statusCode() == 200 : me.body();
          var range =
              client.send(
                  HttpRequest.newBuilder(URI.create(base + "/api/files/1/raw"))
                      .header("Range", "bytes=100-199")
                      .GET()
                      .build(),
                  HttpResponse.BodyHandlers.ofByteArray());
          assert range.statusCode() == 206;
          assert range
              .headers()
              .firstValue("Content-Range")
              .orElseThrow()
              .equals("bytes 100-199/1024");
          assert Arrays.equals(range.body(), Arrays.copyOfRange(videoBytes, 100, 200));
          var suffix =
              client.send(
                  HttpRequest.newBuilder(URI.create(base + "/api/files/1/raw"))
                      .header("Range", "bytes=-10")
                      .GET()
                      .build(),
                  HttpResponse.BodyHandlers.ofByteArray());
          assert Arrays.equals(suffix.body(), Arrays.copyOfRange(videoBytes, 1014, 1024));
          try (var requests = Executors.newVirtualThreadPerTaskExecutor()) {
            var tasks = new ArrayList<Callable<Boolean>>();
            for (int i = 0; i < 50; i++) {
              final int start = i * 10;
              tasks.add(
                  () -> {
                    var result =
                        client.send(
                            HttpRequest.newBuilder(URI.create(base + "/api/files/1/raw"))
                                .header("Range", "bytes=" + start + "-" + (start + 99))
                                .GET()
                                .build(),
                            HttpResponse.BodyHandlers.ofByteArray());
                    return result.statusCode() == 206
                        && Arrays.equals(
                            result.body(), Arrays.copyOfRange(videoBytes, start, start + 100));
                  });
            }
            for (var result : requests.invokeAll(tasks)) assert result.get();
          }
          Path imageRoot = temp.resolve("images");
          Files.createDirectories(imageRoot);
          String imageName = "a".repeat(64) + ".png";
          Files.write(imageRoot.resolve(imageName), new byte[] {1, 2, 3});
          var art =
              client.send(
                  HttpRequest.newBuilder(URI.create(base + "/img/" + imageName)).GET().build(),
                  HttpResponse.BodyHandlers.ofByteArray());
          assert art.statusCode() == 200;
          assert Arrays.equals(art.body(), new byte[] {1, 2, 3});
          assert art.headers().firstValue("Cache-Control").orElseThrow().contains("immutable");
          assert client
                  .send(
                      HttpRequest.newBuilder(URI.create(base + "/img/not-an-image.txt"))
                          .GET()
                          .build(),
                      HttpResponse.BodyHandlers.discarding())
                  .statusCode()
              == 404;
          var invalid =
              client.send(
                  HttpRequest.newBuilder(URI.create(base + "/api/files/1/raw"))
                      .header("Range", "bytes=2048-")
                      .GET()
                      .build(),
                  HttpResponse.BodyHandlers.ofByteArray());
          assert invalid.statusCode() == 416;
          db.execute("UPDATE titles SET hidden=1 WHERE id=1");
          assert client
                  .send(
                      HttpRequest.newBuilder(URI.create(base + "/api/files/1/raw")).GET().build(),
                      HttpResponse.BodyHandlers.discarding())
                  .statusCode()
              == 404;
          db.execute("UPDATE titles SET hidden=0 WHERE id=1");
          db.execute("UPDATE users SET can_download=0 WHERE id=1");
          assert client
                  .send(
                      HttpRequest.newBuilder(URI.create(base + "/api/files/1/download"))
                          .GET()
                          .build(),
                      HttpResponse.BodyHandlers.discarding())
                  .statusCode()
              == 403;
          var created = post(client, base + "/api/rooms", Map.of("linkId", 1, "position", 23));
          assert created.statusCode() == 200 : created.body();
          String roomId = JSON.readTree(created.body()).get("id").asText();
          var state =
              post(
                  client,
                  base + "/api/rooms/" + roomId + "/state",
                  Map.of("playing", false, "position", 25));
          assert state.statusCode() == 200 : state.body();
          assert JSON.readTree(state.body()).get("revision").asInt() == 1;
          var unsupported =
              client.send(
                  HttpRequest.newBuilder(URI.create(base + "/api/home")).GET().build(),
                  HttpResponse.BodyHandlers.ofString());
          assert unsupported.statusCode() == 501;
          CatalogTest.run(db, client, base);
          MembersTest.run(db, client, base);
          AccountProgressTest.run(db, client, base, hash);
        }
      }
    } finally {
      try (var paths = Files.walk(temp)) {
        for (var path : paths.sorted(Comparator.reverseOrder()).toList()) Files.delete(path);
      }
    }
    System.out.println(
        "PASS: migrations 1–18, Argon2id, sessions/CSRF, localization cache, 50 concurrent room"
            + " members, ordered commands and reconnect.");
  }

  private static HttpResponse<String> post(HttpClient client, String url, Object body)
      throws Exception {
    return client.send(
        HttpRequest.newBuilder(URI.create(url))
            .header("X-Fsfy", "1")
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(JSON.writeValueAsString(body)))
            .build(),
        HttpResponse.BodyHandlers.ofString());
  }
}
